const insights = $input.first().json.data || [];

if (insights.length === 0) {
  return [{
    json: {
      has_underperformers: false,
      underperforming_ad_ids: [],
      summary: "No ad data found for the last 7 days.",
      total_spend: 0,
      total_impressions: 0,
      total_clicks: 0,
      total_reach: 0,
      overall_ctr: 0,
      ad_details: [],
      paused_ads: []
    }
  }];
}

let totalSpend = 0;
let totalImpressions = 0;
let totalClicks = 0;
let totalReach = 0;
const underperformingAdIds = [];
const adDetails = [];

insights.forEach(ad => {
  const spend = parseFloat(ad.spend || 0);
  const impressions = parseInt(ad.impressions || 0);
  const clicks = parseInt(ad.clicks || 0);
  const reach = parseInt(ad.reach || 0);
  const cpm = parseFloat(ad.cpm || 0);

  // Calculate CTR
  const ctr = impressions > 0 ? (clicks / impressions) * 100 : 0;

  // Determine status
  let status = "normal";
  let reason = "";

  if (ctr < 1 && impressions > 100) {
    status = "underperforming";
    reason = "CTR below 1%";
    underperformingAdIds.push(ad.ad_id);
  } else if (spend > 50 && clicks < 10) {
    status = "underperforming";
    reason = "wasted spend (>$50 with <10 clicks)";
    underperformingAdIds.push(ad.ad_id);
  } else if (ctr > 3) {
    status = "top performer";
    reason = "CTR above 3%";
  }

  totalSpend += spend;
  totalImpressions += impressions;
  totalClicks += clicks;
  totalReach += reach;

  adDetails.push({
    ad_id: ad.ad_id,
    ad_name: ad.ad_name || "Unknown",
    spend: spend.toFixed(2),
    impressions,
    clicks,
    ctr: ctr.toFixed(2),
    cpm: cpm.toFixed(2),
    reach,
    status,
    reason
  });
});

const overallCtr = totalImpressions > 0 ? (totalClicks / totalImpressions) * 100 : 0;

// Build summary
let summary = `Weekly Performance Summary (Last 7 Days)\n\n`;
summary += `Total Spend: $${totalSpend.toFixed(2)}\n`;
summary += `Total Impressions: ${totalImpressions.toLocaleString()}\n`;
summary += `Total Clicks: ${totalClicks.toLocaleString()}\n`;
summary += `Total Reach: ${totalReach.toLocaleString()}\n`;
summary += `Overall CTR: ${overallCtr.toFixed(2)}%\n\n`;
summary += `Ad Performance:\n`;

adDetails.forEach(ad => {
  summary += `\n- ${ad.ad_name}\n`;
  summary += `  Spend: $${ad.spend} | Impressions: ${ad.impressions.toLocaleString()} | Clicks: ${ad.clicks} | CTR: ${ad.ctr}% | CPM: $${ad.cpm} | Reach: ${ad.reach.toLocaleString()}\n`;
  summary += `  Status: ${ad.status.toUpperCase()}`;
  if (ad.reason) summary += ` (${ad.reason})`;
  summary += `\n`;
});

return [{
  json: {
    has_underperformers: underperformingAdIds.length > 0,
    underperforming_ad_ids: underperformingAdIds,
    summary,
    total_spend: totalSpend.toFixed(2),
    total_impressions: totalImpressions,
    total_clicks: totalClicks,
    total_reach: totalReach,
    overall_ctr: overallCtr.toFixed(2),
    ad_details: adDetails,
    paused_ads: []
  }
}];

